sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {

        var getIncDetails = new GlideRecord('incident');
        getIncDetails.get(current.task);

        var incGroup = getIncDetails.assignment_group.getDisplayValue().toLowerCase().toString();
        var incChannel = getIncDetails.contact_type.getDisplayValue().toLocaleLowerCase().toString();

        //interaction details

        var interactionLoc = current.interaction.location.sys_id;
        gs.info('walkup ' + interactionLoc);

        var getWalkUpLoc = new GlideRecord('wu_location_queue');
        getWalkUpLoc.addEncodedQuery('location.sys_idSTARTSWITH' + interactionLoc);
        getWalkUpLoc.query();
        if (getWalkUpLoc.next()) {
			gs.info('walkup ' + getWalkUpLoc.sys_id);

			getIncDetails.x_938076_now_utils_walk_up_location = getWalkUpLoc.sys_id;
           getIncDetails.update();

        }



    } catch (ex) {
        gs.info('Error from walkup ' + ex);
    }

    // if ((incGroup.indexOf('walk') > -1) || (incChannel.indexOf('walk') > -1)) {
    // 	gs.info(' Walkup incGroup ')

    //         var getInteractionLoc = new GlideRecord('interaction');
    //         getInteractionLoc.get(interactionRec);
    //         var interactionLoc = getInteractionLoc.location.sys_id;
    //         var getWalkUpLoc = new GlideRecord('wu_location_queue');
    //         getWalkUpLoc.addEncodedQuery('location.sys_idSTARTSWITH' + interactionLoc);
    //         getWalkUpLoc.query();
    //         if (getWalkUpLoc.next()) {
    //             getIncDetails.x_938076_now_utils_walk_up_location = getWalkUpLoc.sys_id;
    // 			getIncDetails.update();

    // 		}





    // }

})(current, previous);
